#!/usr/bin/env python3
from pathlib import Path
import base64
import hashlib
import shutil

ROOT = Path.cwd()
DST = ROOT / "sound/songs/midi/mus_where_is_the_love.mid"

if not (ROOT / "include/constants/songs.h").exists() or not DST.parent.exists():
    raise SystemExit("ERRO: rode este Python na raiz do pokeemerald-expansion.")

DATA = base64.b64decode("""""")
EXPECTED = "66cd887edbb997b417bad50c56035123db0477dff2fda6c54a982f96967d88ac"

if hashlib.sha256(DATA).hexdigest() != EXPECTED:
    raise SystemExit("ERRO INTERNO: hash do MIDI V5 invalido.")

if DST.exists():
    bak = DST.with_name(DST.name + ".before_hum_fix_v5")
    if not bak.exists():
        shutil.copyfile(DST, bak)
        bak.touch()
        print("[BACKUP]", bak)

DST.write_bytes(DATA)
DST.touch()
print("[WRITE]", DST)

asm = DST.with_suffix(".s")
if asm.exists():
    asm.unlink()
    print("[DELETE]", asm)

for obj in ROOT.glob("build/*/sound/songs/midi/mus_where_is_the_love.o"):
    obj.unlink()
    print("[DELETE]", obj)

print()
print("[OK] WHERE IS THE LOVE - HUM FIX V5 instalado")
print("Removidos apenas os 77 pulsos C4 da Flute Lead entre 21s e 40s.")
print("Intro V4, baixo, piano, bateria, Radio e IDs preservados.")
print()
print("Agora rode:")
print("  make -j9")
